'use strict';
const OPENING_UI6={cityView,storesView,roastersView,bakeryView,bind,render,map,help};
function openingCards6(kind=null){const list=state.opening6.projects.filter(p=>(!kind||p.kind===kind)&&(p.status==='active'||p.closed>=state.week-13));return list.length?`<section class="card" style="margin-bottom:24px"><h2>Příprava a otevření provozů</h2><p class="sub">Čas, prostor, lidé a káva se platí. Kliknutím otevřeš plán, skutečné kroky a zpoždění.</p><div class="cards">${list.map(p=>`<article><span class="badge">${esc(p.city)} · ${p.status==='active'?OPENING_PHASES6[p.phase]:p.status==='completed'?'Otevřeno':'Ukončeno'}</span><h3>${esc(p.name)}</h3><p>${p.elapsed} týdnů přípravy · plán T${p.plannedEnd}${p.closed?' · skutečnost T'+p.closed:''}</p>${p.blocked?`<p class="warning">${esc(p.blocked)}</p>`:''}<button class="soft" data-opening-report6="${p.id}">Plán a skutečný výsledek</button></article>`).join('')}</div></section>`:'';}
function openingProjectDialog6(id){const p=openingById6(id);if(!p)return;show(`<span class="eyelabel">PŘÍPRAVA PROVOZU · ${esc(p.city)}</span><h2>${esc(p.name)}</h2>${rows([['Stav',p.status==='active'?OPENING_PHASES6[p.phase]:p.status==='completed'?'Plný provoz':'Ukončeno'],['Plánovaný termín','T'+p.plannedEnd],['Skutečný postup',p.elapsed+' zaplacených týdnů'],['Zaplacený majetek',money(p.paidCapital)],['Administrativa a vedoucí',money(p.admin+p.managerFee)],['Nábor lidí',money(p.recruitment)],['Prostor, mzdy a odvody před spuštěním',money(p.operating)],['Další zásahy',money(p.extras)],['Rezervovaný tým',p.entity?'Převeden do skutečného provozu':p.people.map(x=>x.name).join(', ')||'Chybí tým']])}${p.blocked?`<p class="warning">${esc(p.blocked)}</p>`:''}<ol>${OPENING_PHASES6.map((name,i)=>`<li>${name} · plán ${p.durations[i]} ${p.durations[i]===1?'týden':'týdny'}${p.phaseHistory.find(x=>x.phase===i)?' · dokončeno T'+p.phaseHistory.find(x=>x.phase===i).finished:''}</li>`).join('')}</ol><p class="sub">Zkušební kavárna má 35 % místní poptávky, výrobna 50 % kapacity. Kompaktní vybavení bez kontroly má při spuštění stav 78 % a potřebuje další týden zkoušky. Tyto podmínky se promítnou do skutečných šarží, zákazníků, nákladů a stavu zařízení.</p>${p.status==='active'&&!p.entity?`<h3>Pravomoci přípravy</h3><p>${esc(p.manager?.name||'Vede zakladatel')} · ${p.manager?MANAGER_STRATEGIES6[openingStyle6(p)].name:'Ruční příprava'}</p><div class="fields">${field('Týdenní limit placených zásahů',input('openingBudget6',p.policy.budget,0,50000,500))}${field('Rezerva · týdny',input('openingReserve6',p.policy.reserve,1,8))}</div><label><input id="openingPersonal6" type="checkbox" ${p.policy.personal?'checked':''}> Povolit osobní strategii vedoucího</label><br><label><input id="openingAccelerate6" type="checkbox" ${p.policy.accelerate?'checked':''}> Povolit urychlení instalace</label><br><label><input id="openingQuality6" type="checkbox" ${p.policy.quality?'checked':''}> Povolit placenou kontrolu kvality</label><div class="actions"><button class="primary" id="openingPolicySave6">Uložit pravomoci</button><button class="soft" id="openingCancel6">Vyúčtovat ukončení přípravy</button>${p.kind==='cafe'?'<button class="soft" data-goto="supply">Sjednat dodavatele kávy</button>':''}</div>${!p.hired&&p.kind!=='roaster'?`<h3>Doplnit rezervaci skutečného pracovníka</h3><select id="openingWorker6">${(p.kind==='cafe'?state.baristaCandidates:state.academy6.bakerCandidates).filter(x=>!academyBusy6(x.pid)).map(x=>option(x.pid,x.name+(x.contract?' · '+x.contract+' období/den':''),null)).join('')}</select><button class="soft" id="openingWorkerAdd6">Rezervovat pracovníka</button>`:''}`:''}<h3>Co se opravdu stalo</h3><div class="table-scroll"><table class="data"><thead><tr><th>Týden a fáze</th><th>Rozhodnutí a důvod</th><th>Platba / výsledek</th></tr></thead><tbody>${p.history.slice().reverse().map(r=>`<tr><td>T${r.week} · ${OPENING_PHASES6[r.phase]}<small>${r.steps} dokončené kroky</small></td><td>${esc(r.author)}<small>${esc(r.action)}</small></td><td>${money(r.operating+r.cost)}<small>${r.trialOutput===null?'Před spuštěním bez tržeb':r.trialProfit!==null?'Zkouška: '+money(r.trialProfit):'Výstup zkoušky: '+number(r.trialOutput)+' '+(p.kind==='roaster'?'kg':'kusů')}</small></td></tr>`).join('')||'<tr><td colspan="3">Příprava zatím neměla skutečný týden.</td></tr>'}</tbody></table></div>`);
 if(el('openingPolicySave6'))el('openingPolicySave6').onclick=()=>act(()=>setOpeningPolicy6(id,{personal:el('openingPersonal6').checked,accelerate:el('openingAccelerate6').checked,quality:el('openingQuality6').checked,budget:Number(el('openingBudget6').value),reserve:Number(el('openingReserve6').value)}),'Pravomoci přípravy uloženy.');
 if(el('openingWorkerAdd6'))el('openingWorkerAdd6').onclick=()=>{try{addOpeningWorker6(id,el('openingWorker6').value);persist();render();openingProjectDialog6(id);}catch(e){toast(e.message);}};
 if(el('openingCancel6'))el('openingCancel6').onclick=()=>{try{const q=openingCancelQuote6(id);confirmAction('Ukončit přípravu '+esc(p.name)+'?',money(q.refund)+' zpět do hotovosti; '+money(q.writeoff)+' odpis již zaplaceného majetku. Poplatky se nevrací, rezervovaní lidé se uvolní.',()=>cancelOpening6(id,q),'Ukončit a vyúčtovat');}catch(e){toast(e.message);}};
 on('[data-goto]',b=>{el('modal').close();goto(b.dataset.goto);});
}
cityView=function(){let html=OPENING_UI6.cityView();for(const p of state.opening6.projects.filter(p=>p.kind==='cafe'&&p.status==='active'&&!p.entity))html=html.replace(new RegExp('<button[^>]*data-open="'+p.location+'"[^>]*>[^<]*</button>'),`<button class="soft wide" data-opening-report6="${p.id}">Probíhá příprava · ${OPENING_PHASES6[p.phase]}</button>`).replace(new RegExp('<button[^>]*data-franchise="'+p.location+'"[^>]*>[^<]*</button>'),'');return openingCards6('cafe')+html;};
storesView=function(){return openingCards6('cafe')+OPENING_UI6.storesView();};
roastersView=function(){return openingCards6('roaster')+OPENING_UI6.roastersView();};
bakeryView=function(){return openingCards6('bakery')+OPENING_UI6.bakeryView();};
map=function(){let html=OPENING_UI6.map();for(const p of state.opening6.projects.filter(p=>p.kind==='cafe'&&p.status==='active'&&!p.entity))html=html.replace(new RegExp('(<button[^>]*data-location="'+p.location+'"[^>]*>)[^<]*(</button>)'),'$1◷$2');return html;};
openDialog=function(id,franchise=false){const l=loc(id),existing=openingReserved6(id);if(existing)return openingProjectDialog6(existing.id);show(`<span class="eyelabel">${esc(l.city)} · PŘÍPRAVA NOVÉHO PROVOZU</span><h2>${esc(l.name)}</h2><p>Prostor → instalace → skutečný tým → zkušební provoz. Před spuštěním kavárna neprodává.</p><div class="fields">${field('Značka',`<select id="openBrand">${brandOptions(state.brands[0].id)}</select>`)}${field('Káva',`<select id="openBlend">${blendOptions(state.blends[0].id)}</select>`)}${field('Návrh vybavení',`<select id="openDesign5">${option('base','Základní kavárna','base')+state.studio5.designs.map(d=>option(d.id,d.name,'base')).join('')}</select>`)}${field('Prostor',`<select id="openSpace5">${Object.entries(PREMISES_SPACES5).map(([k,c])=>option(k,c.name,'existing')).join('')}</select>`)}${field('Smlouva',`<select id="openTenure5">${propertyChoices5('legacy')+option('owned','Koupit budovu','legacy')}</select>`)}${field('Tým na ráno / poledne / večer',`<select id="openingShift6"><option value="lean">Malý začátek · 1 / 1 / 1</option><option value="full">Plný tým podle místní špičky</option></select>`)}${field('Vedoucí přípravy',`<select id="openingManager6">${option('','Vede zakladatel · bez další mzdy','')+state.talents.filter(p=>!academyBusy6(p.pid)).map(p=>option(p.pid,p.name+' · '+MANAGER_STRATEGIES6[CHARACTER_TYPES6[p.character6.trait].strategy].name+' · '+money(p.salary)+'/týden','')).join('')}</select>`)}</div><div id="openingPreview5"></div><button class="primary wide" id="openConfirm">Zahájit placenou přípravu</button>`);
 let q;const read=()=>({location:id,franchise,brand:el('openBrand').value,blend:el('openBlend').value,design:el('openDesign5').value,options:{space:el('openSpace5').value,kind:el('openTenure5').value},managerPid:el('openingManager6').value||null,shifts:el('openingShift6').value==='lean'?[1,1,1]:makeStore(id).daily.shifts}),preview=()=>{try{q=openingQuote6('cafe',read());el('openingPreview5').innerHTML=rows([['Platba nyní · prostor, vybavení a příprava',money(q.cost)],['Hotovost po zahájení',money(state.cash-q.cost)],['Plán bez zdržení',q.totalWeeks+' týdnů · do T'+(state.week+q.totalWeeks-1)],['Držení prostoru / týden',money(q.holdingRent)],['Fixní provoz po otevření · bez kávy a surovin',q.running===null?'Platí partner':money(q.running)],['Rezervovaní skuteční pracovníci',q.staffPids.map(id=>state.baristaCandidates.find(p=>p.pid===id).name).join(', ')||'Franšízový partner'],['Pozdější nábor · platba',money(q.staffPids.length*crewFee5())]])+'<p class="sub">Mzdy začnou při náboru, vedoucí se platí od zahájení. Káva není v ceně: po zahájení sjednej dodavatele v zásobování. Bez zaplacené kávy se spuštění zdrží. Kompaktní vybavení bez placené kontroly prodlouží zkoušku o týden. Menší tým omezuje kapacitu obsluhy.</p>';el('openConfirm').disabled=state.cash<q.cost||state.over;}catch(e){q=null;el('openingPreview5').textContent=e.message;el('openConfirm').disabled=true;}};
 for(const key of ['openBrand','openBlend','openDesign5','openSpace5','openTenure5','openingShift6','openingManager6'])el(key).onchange=preview;preview();el('openConfirm').onclick=()=>{try{if(!q)throw Error('Vyber platnou přípravu.');const p=startOpening6('cafe',read(),q);persist();render();openingProjectDialog6(p.id);toast('Příprava zahájena. Sjednej dodávky kávy.');}catch(e){toast(e.message);}};
};
bind=function(){OPENING_UI6.bind();on('[data-opening-report6]',b=>openingProjectDialog6(b.dataset.openingReport6));on('[data-bakery-buy5]',b=>{try{const data={type:b.dataset.bakeryBuy5,city:el('bakeryCity5').value},q=openingQuote6('bakery',data);confirmAction('Připravit vlastní pekárnu?',money(q.cost)+' nyní; plán '+q.totalWeeks+' týdnů. '+q.staffPids.length+' skutečných pekařů, další nábor '+money(q.staffPids.length*8000)+', placené držení místa a mzdy. Zkouška má polovinu fyzické kapacity.',()=>startOpening6('bakery',data,q),'Zahájit přípravu');}catch(e){toast(e.message);}});};
render=function(){OPENING_UI6.render();el('next').disabled=state.over||!state.stores.length&&!hasOpeningWork6();};
help=function(){OPENING_UI6.help();const p=document.createElement('p');p.textContent='Nová kavárna, pražírna i pekárna vzniká postupně. Zaplacený prostor a vybavení je rozestavěný majetek; držení místa, správní poplatky, nábor a mzdy jsou další skutečné náklady. Vedoucí s povahou průkopníka a provozní dovedností alespoň 75 může při povolení instalaci urychlit. Kvalitář v limitu a rezervě zaplatí kontrolu 1 800 Kč; kompaktní vybavení pak nezpůsobí dodatečný týden zkoušky. Šetřílek nepřidává nepovolené investice. Přehled přípravy ukazuje plán, zásahy a skutečné termíny.';el('modalContent').append(p);};el('help').onclick=help;render();
